def named(x,path=''):
 if isinstance(x,dict):
  for k,v in x.items():
   if k in ('id','name','title') and isinstance(v,str):yield(path+'/'+k,v)
   yield from named(v,path+'/'+k)
 elif isinstance(x,list):
  for i,v in enumerate(x):yield from named(v,path+'/'+str(i))
