 name=pathlib.Path(b['repo']).name; data=json.loads((P/'baselines'/f'{name}-data.json').read_text())
 for e in entries:
  matches=[dict(path=k,value=v) for k,v in named(data) if any(a.lower() in v.lower() for a in e['aliases'])]
  dedup.append(dict(baseline=name,head=b['head'],entity_id=e['id'],aliases=e['aliases'],matches=matches))
